CREATE TABLE acct (id INTEGER PRIMARY KEY, owner TEXT, balance INTEGER);
INSERT INTO acct VALUES (1, 'ann', 100), (2, 'bob', 50);
BEGIN;
UPDATE acct SET balance = balance - 30 WHERE id = 1;
UPDATE acct SET balance = balance + 30 WHERE id = 2;
SELECT * FROM acct;
ROLLBACK;
SELECT * FROM acct;
BEGIN TRANSACTION;
UPDATE acct SET balance = balance - 30 WHERE id = 1;
UPDATE acct SET balance = balance + 30 WHERE id = 2;
COMMIT;
SELECT * FROM acct;
BEGIN;
CREATE TABLE temp (id INTEGER PRIMARY KEY);
INSERT INTO temp VALUES (1);
DROP TABLE acct;
SELECT * FROM temp;
ROLLBACK;
SELECT * FROM temp;
